import React, { useEffect, useState } from "react";
import api from "../api";
import io from "socket.io-client";

type Comment = {
  _id: string;
  body: string;
  createdAt: string;
  author?: {
    firstName?: string;
    lastName?: string;
    email?: string;
  };
};

type Ticket = {
  _id: string;
  title: string;
  description?: string;
  category: "Billing" | "Technical" | "General";
  status: string;
  priority: string;
  createdBy: string;
  assignee?: string | null;
  createdAt: string;
  comments?: Comment[];
};

interface Props {
  name: string;
}

const UserDashboard: React.FC<Props> = ({ name }) => {
  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");
  const [category, setCategory] = useState("");
  const [message, setMessage] = useState("");
  const [error, setError] = useState("");

  const [myTickets, setMyTickets] = useState<Ticket[]>([]);
  const [selectedTicket, setSelectedTicket] = useState<Ticket | null>(null);

  const [isEditingTitle, setIsEditingTitle] = useState(false);
  const [isEditingDescription, setIsEditingDescription] = useState(false);
  const [editTitle, setEditTitle] = useState("");
  const [editDescription, setEditDescription] = useState("");

  const [newComment, setNewComment] = useState("");
  const [isAddingComment, setIsAddingComment] = useState(false);

  const [socket, setSocket] = useState<any>(null);

  // -------------------------------
  // FETCH TICKETS (list)
  // -------------------------------
  const fetchTickets = async () => {
    try {
      const res = await api.get<Ticket[]>("/tickets");
      setMyTickets(res.data);
    } catch (err: any) {
      setError(err?.response?.data?.message || "Failed to fetch tickets");
    }
  };

  // -------------------------------
  // FETCH FULL TICKET
  // -------------------------------
  const fetchFullTicket = async (id: string) => {
    try {
      const res = await api.get<Ticket>(`/tickets/${id}`);
      setSelectedTicket(res.data);
    } catch {
      setError("Failed to fetch ticket");
    }
  };

  // -------------------------------
  // CREATE TICKET
  // -------------------------------
  const handleCreateTicket = async (e: React.FormEvent) => {
    e.preventDefault();
    setError("");
    setMessage("");

    try {
      await api.post("/tickets", { title, description, category });
      setTitle("");
      setDescription("");
      setCategory("");
      setMessage("Ticket created successfully!");
      fetchTickets();
    } catch (err: any) {
      setError(err?.response?.data?.message || "Create failed");
    }
  };

  // -------------------------------
  // DELETE TICKET
  // -------------------------------
  const deleteTicket = async (id: string) => {
    try {
      await api.delete(`/tickets/${id}`);
      setMyTickets((prev) => prev.filter((t) => t._id !== id));
      if (selectedTicket?._id === id) setSelectedTicket(null);
    } catch {
      setError("Delete failed");
    }
  };

  // -------------------------------
  // UPDATE TITLE / DESCRIPTION
  // -------------------------------
  const saveField = async (payload: Partial<Ticket>, done: () => void) => {
    if (!selectedTicket) return;

    try {
      const res = await api.patch(`/tickets/${selectedTicket._id}`, payload);
      const updated = res.data as Ticket;

      setMyTickets((prev) =>
        prev.map((t) => (t._id === updated._id ? updated : t))
      );

      setSelectedTicket(updated);
      done();
    } catch {
      setError("Update failed");
    }
  };

  // -------------------------------
  // ADD COMMENT
  // -------------------------------
  const addComment = async () => {
    if (!selectedTicket || !newComment.trim()) return;

    try {
      setIsAddingComment(true);
      const res = await api.post(`/tickets/${selectedTicket._id}/comments`, {
        body: newComment.trim(),
      });

      const updated = res.data as Ticket;
      setMyTickets((prev) =>
        prev.map((t) => (t._id === updated._id ? updated : t))
      );
      setSelectedTicket(updated);
      setNewComment("");
    } catch {
      setError("Failed to add comment");
    } finally {
      setIsAddingComment(false);
    }
  };

  // -------------------------------
  // SOCKET SETUP
  // -------------------------------
  useEffect(() => {
    const s = io("http://localhost:5050", { withCredentials: true } as any);
    setSocket(s);

    return () => {
      s.disconnect();
    };
  }, []);

  // -------------------------------
  // SOCKET LISTENERS
  // -------------------------------
  useEffect(() => {
    if (!socket) return;

    socket.on("ticketCreated", fetchTickets);

    socket.on("ticketUpdated", (updated: Ticket) => {
      setMyTickets((prev) =>
        prev.map((t) => (t._id === updated._id ? updated : t))
      );
      setSelectedTicket((prev) =>
        prev && prev._id === updated._id ? updated : prev
      );
    });

    socket.on("ticketDeleted", (id: string) => {
      setMyTickets((prev) => prev.filter((t) => t._id !== id));
      if (selectedTicket?._id === id) setSelectedTicket(null);
    });

    return () => {
      socket.off("ticketCreated", fetchTickets);
      socket.off("ticketUpdated");
      socket.off("ticketDeleted");
    };
  }, [socket, selectedTicket]);

  // -------------------------------
  // INITIAL LOAD
  // -------------------------------
  useEffect(() => {
    fetchTickets();
  }, []);

  // -------------------------------
  // RENDER
  // -------------------------------
  return (
    <div>
      <h2>User Dashboard</h2>
      <p>Welcome, {name}!</p>

      {/* CREATE TICKET */}
      <h3>Create Ticket</h3>

      <form onSubmit={handleCreateTicket}>
        <input value={title} onChange={(e) => setTitle(e.target.value)} />
        <textarea
          value={description}
          onChange={(e) => setDescription(e.target.value)}
        />
        <select value={category} onChange={(e) => setCategory(e.target.value)}>
          <option value="">Select Category</option>
          <option value="Technical">Technical</option>
          <option value="Billing">Billing</option>
          <option value="General">General</option>
        </select>
        <button type="submit">Create</button>
      </form>

      {error && <p style={{ color: "red" }}>{error}</p>}
      {message && <p>{message}</p>}

      {/* TICKET LIST */}
      <h3>My Tickets</h3>

      <ul>
        {myTickets.map((t) => (
          <li
            key={t._id}
            onClick={() => {
              setSelectedTicket(t);
              setEditTitle(t.title);
              setEditDescription(t.description || "");
              fetchFullTicket(t._id);
            }}
          >
            {t.title}
          </li>
        ))}
      </ul>

      {/* DETAILS */}
      {selectedTicket && (
        <div>
          <h3>Details</h3>

          <p>
            <strong>Title:</strong>{" "}
            {!isEditingTitle ? (
              <>
                {selectedTicket.title}
                <button onClick={() => setIsEditingTitle(true)}>Edit</button>
              </>
            ) : (
              <>
                <input
                  value={editTitle}
                  onChange={(e) => setEditTitle(e.target.value)}
                />
                <button
                  onClick={() =>
                    saveField({ title: editTitle }, () =>
                      setIsEditingTitle(false)
                    )
                  }
                >
                  Save
                </button>
              </>
            )}
          </p>

          <p>
            <strong>Description:</strong>{" "}
            {!isEditingDescription ? (
              <>
                {selectedTicket.description}
                <button onClick={() => setIsEditingDescription(true)}>
                  Edit
                </button>
              </>
            ) : (
              <>
                <textarea
                  value={editDescription}
                  onChange={(e) => setEditDescription(e.target.value)}
                />
                <button
                  onClick={() =>
                    saveField({ description: editDescription }, () =>
                      setIsEditingDescription(false)
                    )
                  }
                >
                  Save
                </button>
              </>
            )}
          </p>

          <h4>Comments</h4>

          <ul>
            {selectedTicket.comments?.map((c) => (
              <li key={c._id}>
                <strong>{c.author?.email || "Unknown"}:</strong> {c.body}
              </li>
            ))}
          </ul>

          <textarea
            value={newComment}
            onChange={(e) => setNewComment(e.target.value)}
          />

          <button onClick={addComment} disabled={isAddingComment}>
            Add Comment
          </button>

          <br />
          <button onClick={() => deleteTicket(selectedTicket._id)}>
            Delete Ticket
          </button>
          <button onClick={() => setSelectedTicket(null)}>Close</button>
        </div>
      )}
    </div>
  );
};

export default UserDashboard;
